const body = $input.item.json.body || {};
const username = (body.username || '').trim().toLowerCase().replace(/^@/, '');
if (!username) throw new Error('Missing username');
return { json: { username } };

const bundle = $input.item.json.data || $input.item.json;
const profile = bundle.profile || {};
const posts = bundle.posts || [];
const insights = bundle.caption_insights || [];
if (!profile.id) throw new Error('Profile not found in bundle');

let raw = {};
try { raw = profile.raw_profile_data ? (typeof profile.raw_profile_data === 'string' ? JSON.parse(profile.raw_profile_data) : profile.raw_profile_data) : {}; } catch (e) {}

// Filter to last 90 days for influencer metrics
const cutoff = Date.now() - 90 * 86400000;
const recentPosts = posts.filter(p => p.posted_at && new Date(p.posted_at).getTime() >= cutoff);
const totalPosts = recentPosts.length;
if (totalPosts === 0) { const f = profile.followers_count || 0; let tier = 'nano'; if (f >= 5000000) tier = 'celebrity'; else if (f >= 1000000) tier = 'mega'; else if (f >= 200000) tier = 'macro'; else if (f >= 50000) tier = 'mid'; else if (f >= 10000) tier = 'micro'; return { json: { ig_handle: profile.ig_handle, followers_count: f, total_posts_90d: 0, total_videos_90d: 0, total_carousels_90d: 0, follower_tier: tier, is_active_creator: false, activity_status: 'abandoned', last_calculated_at: new Date().toISOString() } }; }

const videos = recentPosts.filter(p => p.type === 'video' || p.type === 'reel');
const carousels = recentPosts.filter(p => p.type === 'carousel');
const sumLikes = recentPosts.reduce((s, p) => s + (p.likes_count || 0), 0);
const sumComments = recentPosts.reduce((s, p) => s + (p.comments_count || 0), 0);
const sumViews = videos.reduce((s, p) => s + (p.views_count || 0), 0);
const avg_likes = Math.round(sumLikes / totalPosts);
const avg_comments = Math.round(sumComments / totalPosts);
const avg_views = videos.length > 0 ? Math.round(sumViews / videos.length) : 0;
const median = arr => { if (!arr.length) return 0; const s = [...arr].sort((a, b) => a - b); const m = Math.floor(s.length / 2); return s.length % 2 ? s[m] : Math.round((s[m - 1] + s[m]) / 2); };
const median_likes = median(recentPosts.map(p => p.likes_count || 0));
const median_views = median(videos.map(p => p.views_count || 0));
const followers = profile.followers_count || 1;
const follower_based_er = parseFloat(((avg_likes + avg_comments) / followers * 100).toFixed(2));
const view_based_er = avg_views > 0 ? parseFloat(((avg_likes + avg_comments) / avg_views * 100).toFixed(2)) : 0;

const engs = recentPosts.map(p => (p.likes_count || 0) + (p.comments_count || 0));
const meanEng = engs.reduce((s, x) => s + x, 0) / Math.max(engs.length, 1);
const variance = engs.reduce((s, x) => s + Math.pow(x - meanEng, 2), 0) / Math.max(engs.length, 1);
const stdDev = Math.sqrt(variance);
const consistency_score = meanEng > 0 ? Math.max(0, Math.min(1, 1 - (stdDev / meanEng))) : 0;

const bestPostByEng = recentPosts.reduce((b, p) => ((p.likes_count + p.comments_count) > ((b && (b.likes_count + b.comments_count)) || 0) ? p : b), null);
const best_post_views = videos.length > 0 ? Math.max(...videos.map(p => p.views_count || 0)) : 0;
const best_post_engagement = bestPostByEng && bestPostByEng.views_count ? parseFloat((((bestPostByEng.likes_count + bestPostByEng.comments_count) / bestPostByEng.views_count) * 100).toFixed(2)) : 0;

const commercialInsights = insights.filter(i => i.commercial_intent);
const ctaInsights = insights.filter(i => i.cta_present);
const allBrands = new Set();
insights.forEach(i => (i.brand_usernames || []).forEach(b => allBrands.add(b)));
const total_brand_collaborations = commercialInsights.length;
const unique_brands_count = allBrands.size;
const commercial_post_rate = parseFloat((commercialInsights.length / totalPosts).toFixed(2));
const cta_usage_rate = parseFloat((ctaInsights.length / totalPosts).toFixed(2));
const brand_diversity_score = total_brand_collaborations > 0 ? parseFloat((unique_brands_count / total_brand_collaborations).toFixed(2)) : 0;
const brandCounts = {};
insights.forEach(i => (i.brand_usernames || []).forEach(b => { brandCounts[b] = (brandCounts[b] || 0) + 1; }));
const top_brand_partners = Object.entries(brandCounts).sort((a, b) => b[1] - a[1]).slice(0, 10).map(([handle, count]) => ({ handle, count }));

let follower_tier = 'nano';
if (followers >= 5000000) follower_tier = 'celebrity';
else if (followers >= 1000000) follower_tier = 'mega';
else if (followers >= 200000) follower_tier = 'macro';
else if (followers >= 50000) follower_tier = 'mid';
else if (followers >= 10000) follower_tier = 'micro';

const lastPostDate = recentPosts[0] ? new Date(recentPosts[0].posted_at) : null;
const daysSinceLastPost = lastPostDate ? Math.floor((Date.now() - lastPostDate.getTime()) / 86400000) : 999;
const is_active_creator = daysSinceLastPost <= 30;
let activity_status = 'active';
if (daysSinceLastPost > 90) activity_status = 'abandoned';
else if (daysSinceLastPost > 30) activity_status = 'dormant';

let gps = 0;
gps += Math.min(30, view_based_er * 6);
gps += Math.min(25, (totalPosts / 90) * 50);
gps += daysSinceLastPost <= 7 ? 20 : daysSinceLastPost <= 30 ? 12 : 5;
gps += Math.min(15, consistency_score * 15);
gps += Math.min(10, best_post_engagement);
const growth_potential_score = Math.round(Math.max(0, Math.min(100, gps)));
const rank_score = parseFloat((view_based_er * 5 + growth_potential_score * 0.4 + (is_active_creator ? 10 : 0) + Math.log10(followers) * 2).toFixed(2));

const tierBaseRates = { nano: [500, 2500], micro: [2500, 10000], mid: [10000, 30000], macro: [30000, 100000], mega: [100000, 300000], celebrity: [300000, 1000000] };
const [baseMin, baseMax] = tierBaseRates[follower_tier];
let mult = 1.0;
if (view_based_er < 1) mult = 0.7;
else if (view_based_er <= 3) mult = 1.0;
else if (view_based_er <= 5) mult = 1.3;
else mult = 1.5;
const estimated_min_rate = Math.round(baseMin * mult);
const estimated_max_rate = Math.round(baseMax * mult);
const recommended_use_cases = [];
if (view_based_er >= 3) recommended_use_cases.push('engagement');
if (view_based_er >= 1) recommended_use_cases.push('awareness');
if (cta_usage_rate >= 0.2) recommended_use_cases.push('conversion');
if (followers >= 50000) recommended_use_cases.push('reach');

const account_age_days = profile.created_at ? Math.floor((Date.now() - new Date(profile.created_at).getTime()) / 86400000) : null;

const payload = {
  ig_handle: profile.ig_handle,
  followers_count: followers,
  total_posts_90d: totalPosts,
  total_videos_90d: videos.length,
  total_carousels_90d: carousels.length,
  posting_frequency_per_day: parseFloat((totalPosts / 90).toFixed(2)),
  posting_frequency_per_week: parseFloat((totalPosts / (90 / 7)).toFixed(2)),
  avg_likes, avg_comments, avg_views, median_likes, median_views,
  follower_based_er, view_based_er,
  best_post_views, best_post_engagement,
  consistency_score: parseFloat(consistency_score.toFixed(2)),
  total_brand_collaborations, unique_brands_count, commercial_post_rate, cta_usage_rate, brand_diversity_score, top_brand_partners,
  follower_tier, account_age_days, is_active_creator, activity_status,
  growth_potential_score, rank_score,
  estimated_min_rate, estimated_max_rate, recommended_use_cases,
  last_calculated_at: new Date().toISOString()
};

return { json: payload };
